  "code": "def generated_loss(batch, model_output, extra):
    # Required interface keys are typically log_prob_w/log_prob_l; fall back to common aliases.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logprob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('chosen_log_prob', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logprob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('rejected_log_prob', None)

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))
    scale = float(hp.get('scale', 1.5954178645298371))
    eps = float(hp.get('eps', 0.05))

    # If required tensors are missing, return a finite scalar zero loss rather than erroring.
    if (lpw is None) or (lpl is None):
        if weight is not None:
            return (weight * 0.0).mean()
        if model_output is not None and isinstance(model_output, dict):
